import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search product inventory by name (case-insensitive).',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query matched against product names.' },
          limit: { type: 'integer', description: 'Maximum number of results to return (1-10).', minimum: 1, maximum: 10 }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { query, limit } = args;
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }
